/// §9.4: the catalog version the engine registers — the newest entry of `patches/patches.json`,
/// read by `build.rs` (SURFACE §7.4, §11.3).
pub fn catalog_version() -> &'static str {
    CATALOG_VERSION
}

/// TS `CATALOG_VERSION`: the same as `catalog_version()`.
pub const CATALOG_VERSION: &str = env!("JACKIOH_CATALOG_VERSION");

/// TS `CATALOG`: every def in `catalog.json`, script or no script, in the file's order. Parsed once,
/// on first use; the catalog is one of the two statics a pure crate may hold (SURFACE §3).
pub static CATALOG: LazyLock<CardDefs> = LazyLock::new(|| {
    serde_json::from_str(catalog_json()).unwrap_or_else(|error| panic!("crates/cards/catalog.json: {error}"))
});

/// TS `CATALOG_IDS`: every catalog id, in `catalog.json` order (`core-001` … `classicplus-t-ai-10`).
pub static CATALOG_IDS: LazyLock<Vec<String>> = LazyLock::new(|| CATALOG.keys().cloned().collect());

/// A def by catalog id. Panics rather than returning `None`: a card file names a real card.
pub fn card_def(id: &str) -> CardDef {
    match CATALOG.get(id) {
        Some(def) => def.clone(),
        None => panic!("no catalog entry \"{id}\" (crates/cards/catalog.json)"),
    }
}

/// A def by its SPEC §5 index ("43", "51.1", "T-rush") within its set — an index is unique only
/// there (B2.2) — for tests and pools named by index.
pub fn card_def_by_index(set: SetName, index: &str) -> CardDef {
    match CATALOG
        .values()
        .find(|entry| entry.set == set && entry.index == index)
    {
        Some(def) => def.clone(),
        None => panic!("no {set} catalog entry with index \"{index}\" (crates/cards/catalog.json)"),
    }
}

/// TS `scriptsOf()`: every card file's scripts, by catalog id, in `REGISTRY`'s (id) order. Each
/// call builds them anew; the engine holds the copy `register_all` handed it.
pub fn scripts_of() -> IndexMap<String, CardScripts> {
    REGISTRY
        .iter()
        .map(|(id, script)| ((*id).to_string(), script()))
        .collect()
}

/// ME-STATS (Meditative #50 CN Tech): `data/win_rates.json` as compiled in, the table CN Tech
/// reads. A sidecar like `flavour.json`: no rule but CN Tech reads it, and only through the engine's
/// registered copy.
pub fn win_rates_json() -> &'static str {
    include_str!("../data/win_rates.json")
}

/// ME-STATS: the compiled win-rate table, parsed once, on first use.
pub static WIN_RATES: LazyLock<WinRateTable> = LazyLock::new(|| {
    serde_json::from_str(win_rates_json())
        .unwrap_or_else(|error| panic!("crates/cards/data/win_rates.json: {error}"))
});

/// R2386000: the shipped sets (`SHIPPED_SETS`, in order) of which `table` holds no row M #50 CN Tech
/// or M+ #2 NA Tech can pick: a deckable card of the set (never a token) with at least
/// `CN_TECH_MIN_GAMES` games. The compiled table leaves none (CN Tech's R2386000 test).
pub fn sets_without_win_rates(table: &WinRateTable) -> Vec<SetName> {
    use jackioh_engine::config::CN_TECH_MIN_GAMES;
    SHIPPED_SETS
        .into_iter()
        .filter(|set| {
            !table.cards.iter().any(|row| {
                row.games >= CN_TECH_MIN_GAMES
                    && CATALOG
                        .get(&row.id)
                        .is_some_and(|def| def.set == *set && jackioh_engine::catalog::deckable(def))
            })
        })
        .collect()
}

/// Registers the shipped catalog (§9.4) and the card scripts with the engine (SURFACE §7.4), and where
/// the older shipped catalogs a replay folds under are found (R767000): the engine's `OnceLock`s are
/// set here, once per process, and read-only after. Idempotent: a second
/// call does nothing. A test that wants fixture cards uses the testkit's thread-local override
/// (`testkit::register_scripts`, SURFACE §8), never a second registration.
pub fn register_all() {
    static REGISTERED: OnceLock<()> = OnceLock::new();
    REGISTERED.get_or_init(|| {
        jackioh_engine::catalog::register_catalog(
            CATALOG.clone(),
            CATALOG_VERSION,
            WIN_RATES.clone(),
            CODE_BLOCKS,
        );
        jackioh_engine::catalog::register_card_metrics(jackioh_engine::CardMetrics {
            code_lines: CODE_LINES,
            busted: BUSTED,
            complicated: COMPLICATED,
        });
        jackioh_engine::scripts::register_scripts(scripts_of());
        jackioh_engine::catalog::register_shipped(history::shipped_catalog);
    });
}

/// R767000, R2657000: `scripts` with "Can't be in Defense Position" as the static flag `never_defense`
/// it was through v0.5.9f, on the faces that printed it (`base`, `radiant`): the kept script of each card
/// that prints Can't Defend since #2657. It builds on the card's script as it stands, which differs from
/// v0.5.9f's in that flag alone; a later change to one of those scripts keeps v0.5.9f's whole first.
pub(crate) fn never_defense_kept(mut scripts: CardScripts, base: bool, radiant: bool) -> CardScripts {
    for (face, printed) in [(&mut scripts.base, base), (&mut scripts.radiant, radiant)] {
        if printed {
            let mut flags = face.static_flags.clone().unwrap_or_default();
            flags.never_defense = Some(true);
            face.static_flags = Some(flags);
        }
    }
    scripts
}

/// The card files' tests' `scenario()`: the shipped cards registered first (TS's vitest globalSetup,
/// which the engine's testkit cannot do: it cannot name this crate), then the testkit's harness.
#[cfg(test)]
pub(crate) fn scenario(opts: serde_json::Value) -> jackioh_engine::testkit::Scenario {
    register_all();
    jackioh_engine::testkit::scenario(opts)
}

/// Apply one effect as `controller`'s, the way `resolve.rs` runs a hook's effects, with no card as its
/// source: a test's stand-in for whatever would have run it (an open Marketplace's first Credits, a
/// summon that is no play).
#[cfg(test)]
pub(crate) fn run_as(
    s: &mut jackioh_engine::testkit::Scenario,
    effect: jackioh_engine::Effect,
    controller: jackioh_engine::PlayerId,
) -> Vec<jackioh_engine::GameEvent> {
    use jackioh_engine::resolve::{HookOptions, make_context};
    let mut events: Vec<jackioh_engine::GameEvent> = Vec::new();
    let mut rng = jackioh_engine::rng::Rng::new(&s.state().seed, s.state().rng_cursor);
    {
        let mut sink = jackioh_engine::EngineSink::new(s.state_mut(), &mut events, &mut rng);
        let mut ctx = make_context(
            &mut sink,
            None,
            HookOptions {
                controller: Some(controller),
                ..Default::default()
            },
        );
        (effect.apply)(&mut ctx);
    }
    s.state_mut().rng_cursor = rng.cursor();
    events
}

