/// R2250000: `player` plays the Resource of `def_id` longest in their hand, with `targets` declared
/// (`Value::Null` for none). Panics when the hand holds none or `reduce` refuses the play.
#[cfg(test)]
pub(crate) fn play_resource<'a>(
    s: &'a mut jackioh_engine::testkit::Scenario,
    player: jackioh_engine::PlayerId,
    def_id: &str,
    targets: serde_json::Value,
) -> &'a mut jackioh_engine::testkit::Scenario {
    let instance_id = resources_in_hand(s, player)
        .into_iter()
        .find(|card| card.def_id == def_id)
        .unwrap_or_else(|| panic!("{player}'s hand holds a {def_id}"))
        .id;
    s.act(
        jackioh_engine::ActionBody::Play {
            instance_id,
            zone: None,
            x: None,
            embiggen: None,
            equip: None,
            tributes: None,
            targets: (!targets.is_null()).then(|| jackioh_engine::prelude::json_as(targets)),
            modes: None,
            plague: None,
            face_down: None,
        },
        player,
        "play the Resource",
    )
}

/// The price a play of p1's `id` reads: with one mana less than `cost`, the play is refused for it.
#[cfg(test)]
pub(crate) fn expect_costs(
    s: &mut jackioh_engine::testkit::Scenario,
    id: &str,
    cost: i32,
    play: serde_json::Value,
) {
    s.state_mut().players.p1.mana.current = cost - 1;
    let refusal = format!("{} costs {cost}, more than your mana", card_def(id).name);
    s.expect_refused_with(|s| s.play(id, play), &refusal);
}

/// R767000: `run` folding under the build's catalog with `scripts` kept for `id`, as a replay of the
/// version a `KEPT_SCRIPTS` row names folds once a later patch ships: a kept script's test before then.
#[cfg(test)]
pub(crate) fn under_kept<T>(id: &str, scripts: CardScripts, run: impl FnOnce() -> T) -> T {
    register_all();
    let shipped: &'static jackioh_engine::ShippedCatalog =
        Box::leak(Box::new(jackioh_engine::ShippedCatalog::new(
            "kept",
            CATALOG.clone(),
            IndexMap::from([(id.to_string(), scripts)]),
        )));
    jackioh_engine::with_shipped(Some(shipped), run)
}

/// `under_kept` with the kept version's own definition of `id`: `old` rewrites the build's into it (a
/// declared number renamed since, which the kept script reads by its old name).
#[cfg(test)]
pub(crate) fn under_kept_as<T>(
    id: &str,
    scripts: CardScripts,
    old: impl FnOnce(&mut CardDef),
    run: impl FnOnce() -> T,
) -> T {
    register_all();
    let mut defs = CATALOG.clone();
    if let Some(def) = defs.get_mut(id) {
        old(def);
    }
    let shipped: &'static jackioh_engine::ShippedCatalog = Box::leak(Box::new(
        jackioh_engine::ShippedCatalog::new("kept", defs, IndexMap::from([(id.to_string(), scripts)])),
    ));
    jackioh_engine::with_shipped(Some(shipped), run)
}

/// R1081000: move the Unit `id`, set up in a unit zone, to stand in its controller's backrow zone `lane`,
/// as a Flying Unit played there stands. No catalog card prints Flying (a random keyword's), and a Unit
/// standing there stays standing whatever its text says, so a card test sets one up so.
#[cfg(test)]
pub(crate) fn stand_in_backrow(s: &mut jackioh_engine::testkit::Scenario, id: &str, lane: i32) {
    use jackioh_engine::prelude::*;
    let state = s.state_mut();
    let mut moving = find_instance(state, id)
        .cloned()
        .expect("the Unit is on the field");
    let player = moving.controller;
    assert!(remove_from_field(
        state,
        &moving,
        RemoveFromFieldOptions::default()
    ));
    let at = ZoneSlot {
        player,
        row: Row::Backrow,
        lane,
    };
    assert!(place_standing_on_field(
        state,
        &mut moving,
        at,
        PlaceOnFieldOptions::default()
    ));
    assert!(stands_in_backrow(
        state,
        find_instance(state, id).expect("placed")
    ));
}

/// R1852000 (Stinkyscape's Starship cards, #1859): p1's main phase with p1's Dormant Starship built
/// from `pieces` — field entries of p1's (`{ "def", "lane", "radiant" }`), each destroyed by a Core
/// #16 Hit Job in the order given, so each fuses its copy into the Starship in that order — and p1's
/// mana as it was before the Hit Jobs. `p1` and `p2` go over each side's defaults, p1's `hand` and
/// `field` beside the Hit Jobs and the pieces; no turn ends by itself. Returns the scenario and the
/// Dormant Starship's id.
#[cfg(test)]
pub(crate) fn built_starship(
    seed: &str,
    pieces: serde_json::Value,
    p1: serde_json::Value,
    p2: serde_json::Value,
) -> (jackioh_engine::testkit::Scenario, String) {
    use jackioh_engine::testkit::{PlayerId, json, pick};
    const HIT_JOB: &str = "core-016";
    const HIT_JOB_COST: i32 = 3;
    let pieces: Vec<serde_json::Value> = pieces.as_array().cloned().unwrap_or_default();
    let listed = |side: &serde_json::Value, key: &str| -> Vec<serde_json::Value> {
        side.get(key)
            .and_then(serde_json::Value::as_array)
            .cloned()
            .unwrap_or_default()
    };
    let mut hand = vec![json!(HIT_JOB); pieces.len()];
    hand.extend(listed(&p1, "hand"));
    let mut field = pieces.clone();
    field.extend(listed(&p1, "field"));
    let mut p1 = merged(json!({ "library": filler(4), "mana": 10 }), p1);
    p1["hand"] = json!(hand);
    p1["field"] = json!(field);
    let mut s = scenario(json!({
        "seed": seed,
        "active": "p1",
        "p1": p1,
        "p2": merged(json!({ "hand": filler(1), "library": filler(4) }), p2),
    }));
    for player in [PlayerId::P1, PlayerId::P2] {
        s.state_mut().players[player].auto_end_turn = Some(false);
    }
    let mana = s.state().players.p1.mana.current;
    let lanes: Vec<i32> = pieces
        .iter()
        .map(|piece| {
            piece["lane"]
                .as_i64()
                .and_then(|lane| i32::try_from(lane).ok())
                .expect("a piece names its lane")
        })
        .collect();
    for lane in lanes {
        s.state_mut().players.p1.mana.current = mana.max(HIT_JOB_COST);
        let targets = pick::unit_at(&s, PlayerId::P1, lane);
        s.play(HIT_JOB, json!({ "targets": targets }));
    }
    s.state_mut().players.p1.mana.current = mana;
    let ship = jackioh_engine::prelude::dormant_starship_of(s.state(), PlayerId::P1)
        .expect("the pieces built p1 a Dormant Starship")
        .id
        .clone();
    (s, ship)
}

