/// R2195003: a Training Grounds snapshot plays exactly as its Core card. The same game, built by
/// `setup` and played by `play` once with each card's id, logs the same events and ends in the same
/// state, the snapshot's id read as the Core card's. Left out are the element its play records
/// (`gameLog.lastElement`, R980), which is its own number's, as R2195003 rules, and the Legacy tag its
/// play counts (`gameLog.playedByTag`), which only a Legacy card carries (R2511000).
#[cfg(test)]
pub(crate) fn expect_plays_as(
    core: &str,
    snapshot: &str,
    setup: impl Fn(&str) -> serde_json::Value,
    play: impl Fn(&mut jackioh_engine::testkit::Scenario, &str),
) {
    let game = |id: &str| {
        let mut s = scenario(setup(id));
        play(&mut s, id);
        let read_as_core = |value: serde_json::Value| -> serde_json::Value {
            serde_json::from_str(&value.to_string().replace(id, core)).unwrap_or_default()
        };
        let events: Vec<serde_json::Value> = events_json(&s).into_iter().map(read_as_core).collect();
        assert!(!events.is_empty(), "{id}: the game logged nothing");
        let mut state = read_as_core(js(s.state()));
        for side in state["players"]
            .as_object_mut()
            .into_iter()
            .flat_map(|players| players.values_mut())
        {
            if let Some(log) = side["gameLog"].as_object_mut() {
                log.remove("lastElement");
                if let Some(by_tag) = log.get_mut("playedByTag").and_then(|tags| tags.as_object_mut()) {
                    by_tag.remove("Legacy");
                }
            }
        }
        (events, state)
    };
    let (core_events, core_state) = game(core);
    let (events, state) = game(snapshot);
    for (n, (was, now)) in core_events.iter().zip(&events).enumerate() {
        assert_eq!(now, was, "{snapshot} plays unlike {core} at event {n}");
    }
    assert_eq!(
        events.len(),
        core_events.len(),
        "{snapshot} logs a different number of events than {core}"
    );
    for (key, was) in core_state.as_object().into_iter().flatten() {
        assert_eq!(
            state.get(key),
            Some(was),
            "{snapshot} ends with another `{key}` than {core}"
        );
    }
    assert_eq!(state, core_state, "{snapshot} ends in another state than {core}");
}

/// R386, B3.4 rule 3's Number row: one Upgrade or Degrade of `card` that draws its declared number
/// `key`, applied as `tune_once` applies that row — `step_param` by the step `steppable_params` offers
/// that way. Panics unless a step that way can move the number; returns the value it moves to.
#[cfg(test)]
fn tune_number(
    s: &mut jackioh_engine::testkit::Scenario,
    card: &str,
    key: &str,
    direction: jackioh_engine::effects::TuneDirection,
) -> i32 {
    use jackioh_engine::prelude::{ParamValueOptions, param_value, step_param, steppable_params};
    let instance = s.card(card).clone();
    let before = param_value(s.state(), Some(&instance), key, ParamValueOptions::default());
    let Some(item) = steppable_params(s.state(), &instance, direction)
        .into_iter()
        .find(|item| item.param.key == key)
    else {
        panic!(
            "{card}: a {} cannot move its number \"{key}\" (R386)",
            direction.as_str()
        );
    };
    step_param(s.card_mut(card), key, item.steps);
    let after = param_value(s.state(), Some(s.card(card)), key, ParamValueOptions::default());
    assert_eq!(after, before + item.delta, "{card} {key}");
    after
}

/// `tune_number` for an Upgrade: the number one step better.
#[cfg(test)]
pub(crate) fn upgrade_number(s: &mut jackioh_engine::testkit::Scenario, card: &str, key: &str) -> i32 {
    tune_number(s, card, key, jackioh_engine::effects::TuneDirection::Upgrade)
}

/// R1438: give `card` Lucky `n`, as a `lucky` rider does once a card is in a hand: a granted keyword
/// that adds to the Lucky the card prints.
#[cfg(test)]
pub(crate) fn give_lucky(s: &mut jackioh_engine::testkit::Scenario, card: &str, n: i32) {
    s.card_mut(card)
        .granted_keywords
        .push(jackioh_engine::Keyword::Lucky { n });
}

/// R386: whether a step `direction` would move `card`'s declared number `key` at all — false for a
/// number already at the bound it would cross (an amount at 1, a cost set at (0)).
#[cfg(test)]
fn can_tune_number(
    s: &jackioh_engine::testkit::Scenario,
    card: &str,
    key: &str,
    direction: jackioh_engine::effects::TuneDirection,
) -> bool {
    jackioh_engine::prelude::steppable_params(s.state(), s.card(card), direction)
        .iter()
        .any(|item| item.param.key == key)
}

/// `can_tune_number` for an Upgrade.
#[cfg(test)]
pub(crate) fn can_upgrade_number(s: &jackioh_engine::testkit::Scenario, card: &str, key: &str) -> bool {
    can_tune_number(s, card, key, jackioh_engine::effects::TuneDirection::Upgrade)
}

/// `can_tune_number` for a Degrade.
#[cfg(test)]
pub(crate) fn can_degrade_number(s: &jackioh_engine::testkit::Scenario, card: &str, key: &str) -> bool {
    can_tune_number(s, card, key, jackioh_engine::effects::TuneDirection::Degrade)
}

/// `tune_number` for a Degrade: the number one step worse.
#[cfg(test)]
pub(crate) fn degrade_number(s: &mut jackioh_engine::testkit::Scenario, card: &str, key: &str) -> i32 {
    tune_number(s, card, key, jackioh_engine::effects::TuneDirection::Degrade)
}

/// TS `s.unit(p, lane)?.id ?? ""`: the unit's instance id, or blank for an empty lane.
#[cfg(test)]
pub(crate) fn unit_or_blank(
    s: &jackioh_engine::testkit::Scenario,
    player: jackioh_engine::PlayerId,
    lane: i32,
) -> String {
    s.unit(player, lane).map(|unit| unit.id).unwrap_or_default()
}

/// TS `toMatchObject`: every key the pattern names holds a matching value; arrays match item by item.
#[cfg(test)]
pub(crate) fn matches_object(actual: &serde_json::Value, pattern: &serde_json::Value) -> bool {
    use serde_json::Value;
    match (actual, pattern) {
        (Value::Object(actual), Value::Object(pattern)) => pattern
            .iter()
            .all(|(key, want)| actual.get(key).is_some_and(|got| matches_object(got, want))),
        (Value::Array(actual), Value::Array(pattern)) => {
            actual.len() == pattern.len()
                && actual
                    .iter()
                    .zip(pattern)
                    .all(|(got, want)| matches_object(got, want))
        }
        _ => actual == pattern,
    }
}

/// Stinkyscape's weapon rack (S06, #1862): p1's turn 9 with each side set up as `p1` and `p2` say, a
/// library of filler to draw unless it names one, and no turn that ends by itself (R345), so a test
/// ends each turn it means to.
#[cfg(test)]
pub(crate) fn weapon_board(
    seed: &str,
    p1: serde_json::Value,
    p2: serde_json::Value,
) -> jackioh_engine::testkit::Scenario {
    let side = |over: serde_json::Value| merged(serde_json::json!({ "library": filler(4) }), over);
    let mut s = scenario(serde_json::json!({ "seed": seed, "p1": side(p1), "p2": side(p2) }));
    for player in jackioh_engine::PLAYER_IDS {
        s.state_mut().players[player].auto_end_turn = Some(false);
    }
    s
}

/// Ends turns until it is `player`'s again: their next turn.
#[cfg(test)]
pub(crate) fn next_turn_of(s: &mut jackioh_engine::testkit::Scenario, player: jackioh_engine::PlayerId) {
    s.end_turn();
    while s.state().active != player {
        s.end_turn();
    }
}

/// The hits among `events`: each `damage` event's target and amount, in order.
#[cfg(test)]
pub(crate) fn hits(events: &[jackioh_engine::GameEvent]) -> Vec<(String, i32)> {
    events
        .iter()
        .filter_map(|event| match event {
            jackioh_engine::GameEvent::Damage {
                target_id, amount, ..
            } => Some((target_id.clone(), *amount)),
            _ => None,
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The catalog parses into `CardDef`s and writes back exactly the JSON it was read from, so the
    /// wire types lose and invent nothing (SURFACE §5.1).
    #[test]
    fn the_catalog_round_trips_through_card_defs() {
        let raw: serde_json::Value = serde_json::from_str(catalog_json()).expect("catalog.json is JSON");
        let typed = serde_json::to_value(&*CATALOG).expect("CardDefs serialize");
        assert_eq!(typed, raw);
        assert_eq!(CATALOG_IDS.first().map(String::as_str), Some("core-001"));
        assert_eq!(card_def("core-002").name, "Bigot");
        assert_eq!(card_def_by_index(SetName::Core, "2").id, "core-002");
    }

    #[test]
    fn the_catalog_version_is_the_newest_patch() {
        let patches: serde_json::Value =
            serde_json::from_str(include_str!("../patches/patches.json")).expect("patches.json is JSON");
        let newest = patches
            .as_array()
            .and_then(|p| p.last())
            .and_then(|p| p.get("version"))
            .cloned();
        assert_eq!(newest, Some(serde_json::Value::from(catalog_version())));
    }
}
